{
  "themes": [
    {
      "cluster": 0,
      "name": "iOS 11 Battery Drain & Crash Bugs",
      "description": "Customers report severe battery loss, device overheating, and apps crashing after updating to iOS 11."
    },
    {
      "cluster": 1,
      "name": "Missing Auto‑Brightness Toggle",
      "description": "Users are unable to disable automatic screen brightness in iOS 11 and find the screen dimming unexpectedly."
    },
    {
      "cluster": 2,
      "name": "Apple Watch Update & UI Glitches",
      "description": "Feedback highlights watchOS update failures, watch face scaling issues, and incompatibility with original chargers."
    },
    {
      "cluster": 3,
      "name": "FaceTime & Face ID Functionality Problems",
      "description": "Customers experience misrouted FaceTime calls, inability to use FaceTime on new devices, and concerns about parental controls for Animoji."
    },
    {
      "cluster": 4,
      "name": "Maps GPS & Location Inaccuracy",
      "description": "Users report GPS drift, missing location data, and search failures in Apple Maps after iOS 11 upgrades."
    },
    {
      "cluster": 5,
      "name": "Siri Voice & Feature Regression",
      "description": "Feedback mentions Siri mishearing commands, loss of song identification, and inability to set multiple timers."
    },
    {
      "cluster": 6,
      "name": "iBooks/Notes PDF & eBook Access Issues",
      "description": "Customers cannot open, download, or retain PDFs, EPUBs, and purchased books, and report notes disappearing after edits."
    },
    {
      "cluster": 7,
      "name": "Mac Hardware Startup & Noise Failures",
      "description": "Users describe Macs that won’t power on, unexpected shutdowns, and high‑pitched whining noises after macOS updates."
    },
    {
      "cluster": 8,
      "name": "Wi‑Fi & Bluetooth Auto‑Connect Bugs",
      "description": "Feedback centers on Wi‑Fi lag, automatic toggling, and Bluetooth devices not reconnecting after iOS 11 updates."
    },
    {
      "cluster": 9,
      "name": "Phishing & Scam Email Verification",
      "description": "Customers seek help identifying whether received emails or messages are fraudulent or legitimate."
    },
    {
      "cluster": 10,
      "name": "Screen Recording & HEVC Video Playback Issues",
      "description": "Users encounter frozen video frames, audio‑only recordings, and incompatibility with HEVC videos in iOS 11 and macOS."
    },
    {
      "cluster": 11,
      "name": "Apple TV HDR & HDMI Compatibility Concerns",
      "description": "Feedback includes complaints about unwanted HDR conversion, HDMI 2.1 support, and remote pairing problems."
    }
  ]
}
